    public static bool Has(string? name) => name is not null && Paths.ContainsKey(name);

    public static IHtmlContent Svg(string name, string? cssClass = null, int size = 20)
    {
        if (!Paths.TryGetValue(name, out var paths))
            return HtmlString.Empty;

        var css = string.IsNullOrWhiteSpace(cssClass) ? string.Empty : $" class=\"{cssClass}\"";
        return new HtmlString(
            $"<svg{css} xmlns=\"http://www.w3.org/2000/svg\" width=\"{size}\" height=\"{size}\" fill=\"currentColor\" viewBox=\"0 0 256 256\" aria-hidden=\"true\">{paths}</svg>");
    }
